#include <filesystem>
#include "usb_research/profile.hpp"
#include <iostream>
#include <stdexcept>

using namespace usb_research;
static void usage(){std::cout<<"usb-config - USB 2.0 descriptor profile builder\n\n"
"Usage:\n  usb-config validate <profile.json> [--mode strict|research]\n  usb-config compile  <profile.json> --out <compiled.json> [--mode strict|research]\n  usb-config show     <profile.json> [--out <directory>]\n";}
int main(int argc,char**argv){try{if(argc<3){usage();return 2;}std::string cmd=argv[1],path=argv[2],mode="";std::string out;for(int i=3;i<argc;++i){std::string a=argv[i];if(a=="--mode"&&i+1<argc)mode=argv[++i];else if(a=="--out"&&i+1<argc)out=argv[++i];else throw std::runtime_error("unknown or incomplete argument: "+a);}Json profile=Json::parse(read_text_file(path));if(mode.empty())mode=profile.at("validation").at("mode").as_string("strict");if(cmd=="validate"){auto r=validate_profile(profile,mode);std::cout<<r.to_json().dump(2)<<"\n";for(const auto&i:r.issues)std::cerr<<(i.fatal?"ERROR ":"WARN  ")<<i.path<<" ["<<i.code<<"] "<<i.message<<"\n";return r.profile_valid?0:1;}if(cmd=="compile"){if(out.empty())throw std::runtime_error("compile requires --out <file>");profile["validation"]["mode"]=mode;auto r=validate_profile(profile,mode);std::cout<<r.to_json().dump(2)<<"\n";if(!r.profile_valid&&mode!="research")return 1;auto cp=compile_profile(profile);write_text_file(out,compiled_summary(cp).dump(2)+"\n");std::cout<<"Compiled descriptor summary written to "<<out<<"\n";return 0;}if(cmd=="show"){auto cp=compile_profile(profile);std::cout<<"Profile: "<<cp.name<<"\nDevice descriptor ("<<cp.device_descriptor.size()<<" bytes): "<<hex_bytes(cp.device_descriptor)<<"\n";for(std::size_t i=0;i<cp.configuration_descriptors.size();++i)std::cout<<"Configuration "<<i<<" ("<<cp.configuration_descriptors[i].size()<<" bytes): "<<hex_bytes(cp.configuration_descriptors[i])<<"\n";for(const auto&[k,v]:cp.string_descriptors)std::cout<<"String lang="<<k.first<<" index="<<static_cast<unsigned>(k.second)<<": "<<hex_bytes(v)<<"\n";if(!out.empty()){std::filesystem::create_directories(out);write_text_file(out+"/compiled-profile.json",compiled_summary(cp).dump(2)+"\n");}return 0;}usage();return 2;}catch(const std::exception&e){std::cerr<<"usb-config: "<<e.what()<<"\n";return 2;}}
